import{_ as r,l as d,o as e,c as i,v as o,p as s,x as t,d as n,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"Codd 关系模型","description":"","frontmatter":{"title":"Codd 关系模型","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/codd-relational.md","filePath":"cs/codd-relational.md","lastUpdated":1789023840000}'),h={name:"cs/codd-relational.md"};function E(B,a,m,_,f,A){const l=d("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="codd-关系模型" tabindex="-1">Codd 关系模型 <a class="header-anchor" href="#codd-关系模型" aria-label="Permalink to &quot;Codd 关系模型&quot;">​</a></h1><div class="epigraph"><p>用关系与一阶谓词谈共享数据，使应用程序不必随存储布局改写；完整性与数据独立性是同一设计。</p><footer>—— Codd, A Relational Model of Data for Large Shared Data Banks, CACM 1970</footer></div><p><a href="/cs/saltzer-e2e-paper">上一课</a>附录对照了分组互联。附录对照，不插入主干。主干已在<a href="/cs/relational-model">关系模型</a>、<a href="/cs/keys-integrity">键与完整性</a>、<a href="/cs/relational-algebra">关系代数</a>里用过元组、键与闭运算；这里对照 <strong>1970 原文的问题</strong>：大型共享库如何摆脱网状/层次指针，使查询成为关系上的运算。不重写 SQL 标准史。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干数据库第一课从套接字与文件的缺口进入：已有字节，尚未命名关系。Codd 1970 针对的是当时的数据独立性危机：存储一变，程序全改。原文给出关系、域、语言层次（代数与演算）以及完整性。1972 年完备性论文把代数与演算对齐，主干代数课已经点名。</p><p><span class="marginnote">System R 与 SEQUEL 是实现与语言落地，不是 1970 文的章节。Selinger 路径选择是 1979。附录不把优化器史插进 Codd 原文。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据是关系；子语言对关系封闭；存储与用户视图分离。键与参照是模式上的断言。主干从 Codd 取走的正是这一层，物理页与 WAL 来自 Gray 一线。读 1970 是为了看主干为何禁止「先讲 B+ 再讲表」。</p>',8)),(e(),s(c,null,{default:t(()=>[p(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PTR%5B%22%E6%8C%87%E9%92%88%E5%BC%8F%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20REL%5B%22%E5%85%B3%E7%B3%BB%20%2B%20%E9%97%AD%E8%BF%90%E7%AE%97%22%5D%0A%20%20REL%20--%3E%20IND%5B%22%E6%95%B0%E6%8D%AE%E7%8B%AC%E7%AB%8B%E6%80%A7%22%5D%0A%20%20REL%20--%3E%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%3A%20%E5%85%B3%E7%B3%BB%20%2F%20%E9%94%AE%20%2F%20%E4%BB%A3%E6%95%B0%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>值连接代替指针，使引用可检查、可优化。后来的 SQL 包语义与 NULL 是工程缝，主干 SQL 课已承认。范式论文（1971/1972）把依赖写成设计工具，主干范式课已取用，本附录不展开分解算法。</p><h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3><p>主干在网络课之后才进入数据库，因为课序是系统栈。把 1970 插在文件字节流之后当「下一课」会打乱「套接字留下的缺口」这一钩子。附录只对照原文问题，不改变课序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要发明 Codd 的 arXiv。也不要把 NoSQL 论战写进 1970。下一篇对照 Diffie–Hellman 1976 如何让没有预共享密钥的双方建立共同秘密，那是公钥课的文献。</p><p>Codd 后来对 SQL 偏离集合语义有批评；主干已在 SQL 课承认包与 NULL，不在本附录重开标准战争。</p><p>对照结束应回到主干<a href="/cs/relational-model">关系模型</a>。1970 文不改变「套接字之后才命名关系」的课序钩子。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><p>附录对照，不插入主干。</p></li><li><p>下一篇对照 Diffie–Hellman 1976。</p></li><li><p>附录对照 Codd 1970：关系、独立性、完整性作为共享库的抽象。</p></li><li><p>主干关系/键/代数课已取用；物理恢复来自后文。</p></li><li><p>不插入网络课与数据库课之间以外的位置——本篇根本不插入主干。</p></li><li><p>出处：Codd, <em>CACM</em> 13(6), 1970。</p></li></ul>',10))])}const S=r(h,[["render",E]]);export{u as __pageData,S as default};
